Certainly! Below is a simple example of a TCP/IP server in C that listens for incoming connections, accepts them, and can receive messages from the client. This example serves a single client at a time.

### TCP/IP Server in C

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Setting socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    // Defining the address of the server
    address.sin_family = AF_INET; // IPv4
    address.sin_addr.s_addr = INADDR_ANY; // Accept connections from any IP address
    address.sin_port = htons(PORT); // Port number

    // Bind the socket to the address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Start listening for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }
    printf("Listening on port %d...\n", PORT);

    // Accept a connection
    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        exit(EXIT_FAILURE);
    }
    printf("Connection accepted.\n");

    // Read data from the client
    int read_size;
    while ((read_size = read(new_socket, buffer, BUFFER_SIZE)) > 0) {
        buffer[read_size] = '\0'; // Null-terminate the string
        printf("Client: %s\n", buffer);

        // Optional: echo back the received message
        send(new_socket, buffer, read_size, 0);
        memset(buffer, 0, BUFFER_SIZE); // Clear the buffer for the next read
    }

    if (read_size == 0) {
        printf("Client disconnected.\n");
    } else if (read_size == -1) {
        perror("read");
    }

    // Close sockets
    close(new_socket);
    close(server_fd);
    return 0;
}
```

### Compile and Run

To compile the server code, you can use `gcc`:

```bash
gcc -o tcp_server tcp_server.c
```

Then you can run the server:

```bash
./tcp_server
```

### Client Example

You will need a TCP/IP client to connect to this server. Here is a simple example of a TCP client in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int sock = 0;
    struct sockaddr_in serv_addr;
    char *hello = "Hello from client!";
    char buffer[BUFFER_SIZE] = {0};

    // Create socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        printf("\n Socket creation error \n");
        return -1;
    }

    serv_addr.sin_family = AF_INET; // IPv4
    serv_addr.sin_port = htons(PORT); // Port number

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        printf("\nInvalid address/ Address not supported \n");
        return -1;
    }

    // Connect to the server
    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        printf("\nConnection Failed \n");
        return -1;
    }

    send(sock, hello, strlen(hello), 0);
    printf("Message sent from client: %s\n", hello);

    int valread = read(sock, buffer, BUFFER_SIZE);
    buffer[valread] = '\0'; // Null-terminate buffer
    printf("Received from server: %s\n", buffer);

    close(sock);
    return 0;
}
```

### Compile and Run Client

Compile the client similarly:

```bash
gcc -o tcp_client tcp_client.c
```

Then run the client in a separate terminal after starting the server:

```bash
./tcp_client
```

### Note

- Make sure you have the necessary permissions to bind to the port, or choose a port number higher than 1024 if running as a non-root user.
- The server currently accepts only one connection before it exits. For multiple connections, you may want to implement a loop to accept multiple client connections and perhaps create a new thread or process for each client.

